package com.cowave.search.common.exception

import org.springframework.http.HttpStatus

/**
 * DSearch 애플리케이션의 기본 예외 클래스.
 * 모든 커스텀 예외는 이 클래스를 상속한다.
 */
sealed class DSearchException(
    message: String,
    val status: HttpStatus,
    cause: Throwable? = null,
) : RuntimeException(message, cause)

// ── 400 Bad Request ─────────────────────────────────────────────

class ElasticQueryException(message: String, cause: Throwable? = null) :
    DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class NotFoundException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

class NotFoundUserException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

class DuplicatedUserException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

class InvalidPasswordException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

class ParameterInvalidException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

class CronParseException(message: String, cause: Throwable? = null) :
    DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class ConvertYamlException(message: String, cause: Throwable? = null) :
    DSearchException(message, HttpStatus.BAD_REQUEST, cause)

class NoSuchAnalyzerException(message: String) :
    DSearchException(message, HttpStatus.BAD_REQUEST)

// ── 401 Unauthorized ────────────────────────────────────────────

class PermissionException(message: String) :
    DSearchException(message, HttpStatus.UNAUTHORIZED)

// ── 500 Internal Server Error ───────────────────────────────────

class IndexingJobFailureException(message: String, cause: Throwable? = null) :
    DSearchException(message, HttpStatus.INTERNAL_SERVER_ERROR, cause)

class ServiceException(message: String, cause: Throwable? = null) :
    DSearchException(message, HttpStatus.INTERNAL_SERVER_ERROR, cause)

