package com.cowave.search.notice

import org.slf4j.LoggerFactory
import org.springframework.scheduling.annotation.Async
import org.springframework.stereotype.Service
import org.springframework.web.client.RestClient

/**
 * Telegram Bot API를 통한 알림 서비스.
 *
 * - WebFlux 없이 spring-web의 RestClient 사용
 * - @Async로 비동기 처리 (색인 완료/실패 알림이 주 흐름을 블로킹하지 않도록)
 * - enabled=false 이면 전송 생략
 */
@Service
class TelegramNoticeService(
    private val restClientBuilder: RestClient.Builder,
    private val properties: TelegramProperties,
) {
    private val logger = LoggerFactory.getLogger(TelegramNoticeService::class.java)

    private val restClient: RestClient by lazy { restClientBuilder.build() }

    @Async
    fun sendMessage(text: String) {
        if (!properties.enabled) return
        if (properties.bot.isBlank() || properties.chat.isBlank()) {
            logger.warn("Telegram 설정이 올바르지 않습니다 (bot/chat 미설정)")
            return
        }

        runCatching {
            restClient
                .post()
                .uri("https://api.telegram.org/bot${properties.bot}/sendMessage")
                .body(mapOf("chat_id" to properties.chat, "text" to text))
                .retrieve()
                .toBodilessEntity()
        }.onFailure { e ->
            logger.warn("Telegram 알림 발송 실패: ${e.message}")
        }
    }
}

