data class CreateDictionaryRequest(
    val keyword: String?,
    val type: Type,
    val value: String?,
)

data class UpdateDictionaryRequest(
    val keyword: String,
    val type: Type,
    val value: String?,
)

// 응답 DTO
data class CompileResult(
    val type: Type,
    val count: Int,
    val filePath: String,
    val fileSize: Long,
)

/**
 * Paginated response wrapper for list endpoints
 */
data class PagedResponse<T>(
    val items: List<T>,
    val total: Long,
    val page: Int,
    val size: Int,
    val totalPages: Int,
) {
    companion object {
        fun <T> of(
            items: List<T>,
            total: Long,
            page: Int,
            size: Int,
        ): PagedResponse<T> {
            val totalPages = if (size > 0) ((total + size - 1) / size).toInt() else 0
            return PagedResponse(items, total, page, size, totalPages)
        }
    }
}

/**
 * Cursor-based paginated response for Search After pagination
 */
data class CursorPagedResponse<T>(
    val items: List<T>,
    val total: Long,
    val cursor: String?,
    val hasNext: Boolean,
)

/**
 * Response for type-specific count query
 */
data class TypeCountResponse(
    val type: Type,
    val count: Long,
)

/**
 * Response for type-specific last modified time query
 */
data class TypeLastModifiedResponse(
    val type: Type,
    val lastModified: java.time.Instant?,
    val count: Long,
)

/**
 * Response for all types last modified time query
 */
data class AllTypesLastModifiedResponse(
    val items: List<TypeLastModifiedResponse>,
)

/**
 * Response for all types count query
 */
data class AllTypesCountResponse(
    val items: List<TypeCountResponse>,
    val totalCount: Long,
)

