            }
        }

        return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
    }

    /**
     * COMPOUND 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createCompoundFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CompoundDictionaryData {
        val compoundMap = mutableMapOf<String, List<String>>()
        val mainWordSet = mutableSetOf<String>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val parts =
                value
                    .split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            compoundMap[key] = parts
            mainWordSet.add(key)
            wordSet.addAll(parts)
        }

        return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
    }

    /**
     * Type에 따른 출력 파일명 생성
     */
    fun getOutputFileName(type: Type): String =
        when (type) {
            Type.STOP -> "stop.dict"
            Type.UNIT -> "unit.dict"
            Type.USER -> "user.dict"
            Type.ENGLISH -> "english.dict"
            Type.SYNONYM -> "synonym.dict"
            Type.UNIT_SYNONYM -> "unit_synonym.dict"
            Type.SPACE -> "space.dict"
            Type.COMPOUND -> "compound.dict"
        }
}
